def witness_admissible (k n : Nat) : Bool :=
  decide (2 ≤ k ∧ 1 ≤ n ∧
    (let a : Fin k → Nat := fun i => if (i : Nat) = 0 then n else if (i : Nat) = 1 then 1 else 0
     (∏ i, (a i)!) ∣ n!))

def witness_value (k n : Nat) : Nat :=
  (∑ i, (if (i : Nat) = 0 then n else if (i : Nat) = 1 then 1 else 0)) - n

def witness (k n : ℕ) : Fin k → ℕ := fun i =>
  if (i : ℕ) = 0 then n else if (i : ℕ) = 1 then 1 else 0

def admissible (k n : ℕ) : Prop :=
  2 ≤ k ∧ 1 ≤ n ∧ (∏ i : Fin k, (witness k n i)!) ∣ n!

def excess (k n : ℕ) : ℕ :=
  (∑ i : Fin k, witness k n i) - n
